        switch (type) {
            case DetectedActivity.WALKING:
                tvWalking.setText(“Walking:” + confidenceText);
                break;
            case DetectedActivity.RUNNING:
                tvRunning.setText(“Running:” + confidenceText);
                break;
            case DetectedActivity.STILL:
                tvSitting.setText(“Sitting:” + confidenceText);
                break;
            case DetectedActivity.ON_FOOT: // You can use this as an approximation for jumping
                tvJumping.setText(“Jumping:” + confidenceText);
                break;
            default:
                // Handle other activity types if needed
                break;
        }
    }
};


