//======================Função para ler uma matriz esparsa de um arquivo=========================
SparseMatrix *lerMatrizEsparsa(std::string nome_arquivo)
{
    std::ifstream arquivo(nome_arquivo);// Abrir arquivo

    if (!arquivo)
    {
        std::cout << "Erro ao abrir o arquivo: " << nome_arquivo << std::endl;
        return nullptr;
    }

    int linhas, colunas;
    arquivo >> linhas >> colunas;// Lê as duas primeiras linhas do arquivo

    SparseMatrix *matriz = new SparseMatrix(linhas, colunas); // Cria um novo objeto SparseMatrix com as dimensões lidas

    int linha, coluna;
    double valor;

    // continua até não ter mais linhas a serem lidas no arquivo
    while (arquivo >> linha >> coluna >> valor) // Lê [linha, coluna, valor]
    {
        matriz->insert(linha, coluna, valor);
    }

    arquivo.close();
    return matriz;
}


//========================== Função para realizar a soma de duas matrizes esparsas===================
SparseMatrix *soma(SparseMatrix *A, SparseMatrix *B)
{
    // Verifica de A e B tem o mesmo tamanho
    if (A->getLinhas() != B->getLinhas() || A->getColunas() != B->getColunas())
    {
        std::cout << "As matrizes devem ter as mesmas dimensões para realizar a soma." << std::endl;
        return nullptr;
    }
    // cria nova matrix resultado, com o mesmo tamanho do arquivo lido
    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), A->getColunas());

    // inserir elementos na matrix resultado
    for (int i = 0; i < A->getLinhas(); i++)
    {
        for (int j = 0; j < A->getColunas(); j++)
        {
            double valorA = A->get(i, j);
            double valorB = B->get(i, j);
            resultado->insert(i, j, valorA + valorB);
        }
    }

    return resultado;
}


// ==============================Função para realizar a multiplicação de duas matrizes esparsas================================
SparseMatrix *multiplicacao(SparseMatrix *A, SparseMatrix *B)
{

    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    SparseMatrix *resultado = new SparseMatrix(A->getLinhas(), B->getColunas());


    for (int i = 0; i < A->getLinhas(); i++) // itera linhas da matriz A
    {
        for (int j = 0; j < B->getColunas(); j++) // itera colunas da matriz B
        {
            double valor = 0.0; // acumular o resultado da multiplicação A e B

            //(i, k) da matriz A é multiplicado pelo elemento na posição (k, j) da matriz B
            for (int k = 0; k < A->getColunas(); k++)
            {
                valor += A->get(i, k) * B->get(k, j);
            }
            resultado->insert(i, j, valor);
        }
    }

    return resultado;
}






