Для этого нужно выполнить следующие шаги:

1. Создать объект GDBusConnection для соединения с шиной.
2. Создать GDBusProxy для интерфейса, который принимает сигналы.
3. Добавить обработчик сигнала на прокси-объекте с помощью функции g_signal_connect().
4. Запустить основной цикл GMainLoop для ожидания и обработки сигналов.

Вот пример кода:

#include <gio/gio.h>

// Обработчик сигнала
void on_signal_received(GDBusProxy *proxy, gchar *sender_name, gchar *signal_name, GVariant *parameters, gpointer user_data)
{
g_print(“Signal received: %s from %s\n”, signal_name, sender_name);

// Получаем параметры сигнала
gchar *param1, *param2;
g_variant_get(parameters, “(ss)”, &param1, &param2);
g_print(“Parameters: %s %s\n”, param1, param2);

// Освобождаем ресурсы
g_free(param1);
g_free(param2);
}

int main(int argc, char **argv)
{
GMainLoop *loop;
GDBusProxy *proxy;
GDBusConnection *connection;

// Подключаемся к шине
connection = g_bus_get_sync(G_BUS_TYPE_SYSTEM, NULL, NULL);

// Создаем прокси для интерфейса, который принимает сигналы
proxy = g_dbus_proxy_new_sync(connection, G_DBUS_PROXY_FLAGS_NONE, NULL, “org.example.MyObject”,
“/org/example/MyObject”, “org.example.MyInterface”, NULL, NULL);

// Добавляем обработчик сигнала
g_signal_connect(proxy, “g-signal”, G_CALLBACK(on_signal_received), NULL);

// Запускаем основной цикл GMainLoop
loop = g_main_loop_new(NULL, FALSE);
g_main_loop_run(loop);

// Освобождаем ресурсы
g_object_unref(proxy);
g_object_unref(connection);
g_main_loop_unref(loop);

return 0;
