/**
 * implementação do construtor da matriz esparsa da classe SparseMatrix.h 
*/
SparseMatrix::SparseMatrix(int m, int n){

    if(m > 0 && n > 0){

        //esses 3 ponteiros são utilizados no código para auxliar na linkagem dos nós.
        Node* f = new Node(0, 0, NULL, f, f);
        Node* fir = f; 
        Node* lb = f;
        //===========

        //instanciando o m_head
        m_head->direita = f;
        m_head->abaixo = f;

        for(int i = 0; i < m; i++){

            for(int c = 1; c < n; c++){

                Node* aux = new Node(i, c, NULL, fir, aux);
                f->direita = aux;
                f = aux;
                lb->direita->abaixo = aux;
                lb = lb->direita;
                delete aux;

            }

            f = fir;
            lb = fir;

            if(i < m - 2){

                Node* aux = new Node(i, 0, NULL, aux, aux);
                f->abaixo = aux;
                f = aux;
                delete aux;

                fir = f;
            }
        }

        fir = m_head->direita;
        for(int col = 0; col < n; col++){

            f->abaixo = fir;

            f = f->direita;
            fir = fir->direita;

        }

        delete f;
        delete fir;
        delete lb;

        matriz = &m_head;

    } else {

        throw range_error("--> valores passados inválidos.");

    }


}

/**
 * Destrutor. Libera toda a memória que foi alocada dinamicamente para a matriz.
*/

 /*
     1 librar memoria de cada linha
     2 liberar memoria alocada m_head
     3 retornar nullptr 
*/

SparseMatrix::~SparseMatrix(){

    Node* linhas = m_head->abaixo; // aponta para [linhas] nó abaixo do nó cabeçalho 'm_head'


    while (linhas != m_head) {

        Node* colunas = linhas->direita;  //aponta para [colunas] nó à direita do nó 'linhas'

        while (colunas != linhas) {

            Node* temp = colunas; // armazenar o nó atual
            colunas = colunas->direita; //apontar para o próximo nó à direita
            delete temp;
        }


        Node* temp = linhas;
        linhas = linhas->abaixo;
        //aponta para o próximo nó abaixo
        delete temp;
    }

    delete m_head;
    matriz = nullptr;

}


void SparseMatrix::insert(int i, int j, double value){

    if(value == 0){} 

    else if (i > 0 && j > 0){

        Node* aux = m_head->direita;
        for(int col = 1; col < j; col++){

            aux = aux->direita;

        }
        for(int lin = 0; lin < i; lin++){

            aux = aux->abaixo;

        }

        aux->valor = value;

    } else {
        throw range_error("--> erro ao passar o endereço. \"Out of Range\"");

    }

}

double SparseMatrix::get(int i, int j){

    if(i > 0 && j > 0){

        Node* aux = m_head;

        for(int col = 0; col < j; col++){
            aux = aux->direita;

        }
        for(int lin = 0; lin < i; lin++){
            aux = aux->abaixo;

        }

        return aux->valor;

    } else {
        throw range_error("--> erro ao passar o endereço. \"Out of Range\"");

    }

}

